window.RP_SESSION={"id":"S-9ac1aab1539b","messages":[{"id":"RP-III-0110233","time":"2026-06-01T21:36:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"...\n...\n...","characters":["P-e6655a038328"]},{"id":"RP-III-0110234","time":"2026-06-01T21:43:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"... 가문의 여러분께.\n\n 어설픈 용맹의 부길드장, 스텔라 스타라이트가 서신을 올립니다.\n\n 먼저, 이 편지가 여러분들께 큰 혼란을 주게될 것이라는 점을 유감으로 생각합니다.\n\n 귀 가문에서 사망한 것으로 사료된 에피메네우스는 생존해 있습니다.\n\n 현재 에피메네우스는 길드에서 생활하고 있으며 육체적으로나 정신적으로 옛날과 다름 없이 독특한 면모를 계속 유지하는 중입니다.\n\n 이 사실이 여러분들의 가문의 지위와 책임에 어떤 영향을 끼질지 예상이 가지 않습니다만 가족에게 생존 사실조차 전하지 않은 지나치게 무례한 그의 행동을 보고서야 이렇게 편지를 올리게 됩니다.\n\n 에피메네우스의 속마음은 잘 모르겠으나 스스로 소란을 일으키지 않고 싶어하는 것으로 예상됩니다. 그의 소식에 대해서 궁금한 점이 있다면 언제든 서신을 보내주시길 바랍니다.\n\n 마지막으로, 한마디를 올려도 될지 고민했지만, 적겠습니다.\n\n 부디 직접 와서 한소리 해주시길 바랍니다. 마음 고생한 사람들만 항상 당할 수는 없지","characters":["P-e6655a038328"]},{"id":"RP-III-0110235","time":"2026-06-01T21:44:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"스텔라는 편지를 동봉하고서 에피메네우스의 가족에게 보냈다.","characters":["P-e6655a038328"]},{"id":"RP-III-0110236","time":"2026-06-01T21:44:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-e6655a038328"]},{"id":"RP-III-0110237","time":"2026-06-01T21:44:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
